arguments.command:
cat << 'EOF' > /tmp/search_feeds.py
import xml.etree.ElementTree as ET
import glob
import os

target_files = [
    '/tmp/coindesk.xml', '/tmp/cointelegraph.xml', '/tmp/decrypt.xml',
    '/tmp/beincrypto.xml', '/tmp/cryptoslate.xml', '/tmp/cryptofox_markets.xml', '/tmp/cryptofox_reg.xml'
]

keywords = ['polymarket', 'indonesia', 'stablecoin', 'hyperliquid', 'uniswap', 'scam']
matches = {k: [] for k in keywords}

for f in target_files:
    if not os.path.exists(f):
        continue
    try:
        tree = ET.parse(f)
        root = tree.getroot()
        channel = root.find('channel')
        if channel is None:
            continue
        source_name = os.path.basename(f).replace('.xml', '')
        for item in channel.findall('item'):
            title = item.find('title').text if item.find('title') is not None else ""
            link = item.find('link').text if item.find('link') is not None else ""
            pub = item.find('pubDate').text if item.find('pubDate') is not None else ""

            for k in keywords:
                if k in title.lower():
                    matches[k].append({'source': source_name, 'title': title, 'link': link, 'pub': pub})
    except Exception as e:
        pass

for k, m in matches.items():
    print(f"\n--- KEYWORD: {k} (found {len(m)}) ---")
    for item in m[:10]:
        print(f"[{item['source']}] {item['title']} ({item['pub']}) -> {item['link']}")
EOF
python3 /tmp/search_feeds.py
